    [MenuItem("Statecraft/Hex Sandbox Import Models")]
    public static void Run()
    {
        try
        {
            Directory.CreateDirectory(Path.Combine(Paths.RepoRoot, "unity", Root));
            Directory.CreateDirectory(Path.Combine(Paths.RepoRoot, "unity", Prefabs));
            foreach (var (source, model, species, tint) in Table) Import(Path.Combine(Paths.RepoRoot, source, model), model, species, tint);
            AssetDatabase.SaveAssets();
        }
        catch (Exception e)
        {
            Debug.LogError("HEX SANDBOX IMPORT FAILED " + e);
            if (Application.isBatchMode) EditorApplication.Exit(1);
            else throw;
        }
    }

    static void Import(string src, string model, string species, Color tint)
    {
        if (!File.Exists(Path.Combine(src, model + ".obj"))) throw new FileNotFoundException($"no {model}.obj in {src}");
        var dir = $"{Root}/{model}";
        Directory.CreateDirectory(Path.Combine(Paths.RepoRoot, "unity", dir));
        foreach (var f in Directory.GetFiles(src)) File.Copy(f, Path.Combine(Paths.RepoRoot, "unity", dir, Path.GetFileName(f)), true);
        AssetDatabase.Refresh();
        bool tree = File.Exists(Path.Combine(src, "leaves.png"));
        Texture2D Tex(string file, bool normal = false, bool alpha = false, int max = 1024)
        {
            var path = $"{dir}/{file}";
            var ti = (TextureImporter)AssetImporter.GetAtPath(path);
            ti.textureType = normal ? TextureImporterType.NormalMap : TextureImporterType.Default;
            ti.alphaIsTransparency = alpha; ti.maxTextureSize = max; ti.mipmapEnabled = true; ti.sRGBTexture = !normal;
            ti.SaveAndReimport();
            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }
        var shader = Shader.Find("Universal Render Pipeline/Lit") ?? throw new InvalidOperationException("URP Lit not found");
        Material Mat(string name, Texture2D albedo, Color colour, Texture2D? normal = null, bool clip = false)
        {
            var m = new Material(shader) { name = name };
            m.SetTexture("_BaseMap", albedo); m.SetColor("_BaseColor", colour); m.SetFloat("_Smoothness", 0.05f);
            if (normal != null) { m.SetTexture("_BumpMap", normal); m.EnableKeyword("_NORMALMAP"); }
            if (clip)
            {
                m.SetFloat("_AlphaClip", 1f); m.SetFloat("_Cutoff", 0.45f); m.EnableKeyword("_ALPHATEST_ON");
                m.SetFloat("_Cull", (float)CullMode.Off); m.renderQueue = (int)RenderQueue.AlphaTest;
            }
            var path = $"{dir}/{species}-{name}.mat";
            AssetDatabase.DeleteAsset(path); AssetDatabase.CreateAsset(m, path);
            return m;
        }
        var go = Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>($"{dir}/{model}.obj"));
        try
        {
            go.name = species;
            int tris = 0;
            // Made once per model: Mat replaces the asset at its path, which would orphan a renderer already using it.
            var bark = tree ? Mat("bark", Tex("bark.jpg", max: 512), Color.white) : null;
            var leaves = tree ? Mat("leaves", Tex("leaves.png", alpha: true, max: 512), tint, clip: true) : null;
            var rock = tree ? null : Mat("rock", Tex("albedo.jpg", max: species.StartsWith("hq_", StringComparison.Ordinal) ? 2048 : 1024), Color.white, File.Exists(Path.Combine(src, "normal.jpg")) ? Tex("normal.jpg", normal: true) : null);
            foreach (var r in go.GetComponentsInChildren<MeshRenderer>())
            {
                var mesh = r.GetComponent<MeshFilter>().sharedMesh; tris += mesh.triangles.Length / 3;
                r.shadowCastingMode = tree || (species.StartsWith("kit_", StringComparison.Ordinal) || species.StartsWith("hq_", StringComparison.Ordinal)) ? ShadowCastingMode.On : ShadowCastingMode.Off;
                if (tree)
                {
                    // gen.mjs writes "bark" then "leaves"; Unity names submesh materials after the OBJ's usemtl.
                    bool leafPart = r.name.Contains("leaves");
                    r.sharedMaterials = r.sharedMaterials.Select((m, i) => m != null && m.name.Contains("leaves") || leafPart ? leaves!
                        : m != null && m.name.Contains("bark") ? bark! : i == 0 ? bark! : leaves!).ToArray();
                }
                else
                {
                    r.sharedMaterials = Enumerable.Repeat(rock!, r.sharedMaterials.Length).ToArray();
                }
            }
            var prefab = $"{Prefabs}/{species}.prefab";
            PrefabUtility.SaveAsPrefabAsset(go, prefab);
            Debug.Log($"HEX SANDBOX MODEL {species} <- {model} tris={tris} tree={tree}");
        }
        finally { Object.DestroyImmediate(go); }
    }
}
